import fitz
import glob

def extract_first_page_text(pdf_path):
    try:
        doc = fitz.open(pdf_path)
        if len(doc) > 0:
            text = doc[0].get_text()
            print(f"--- Text from {pdf_path} (Page 1) ---")
            print(text)
            print("----------------------------------------\n")
        doc.close()
    except Exception as e:
        print(f"Error reading {pdf_path}: {e}")

pdf_files = sorted(glob.glob("/root/paper*.pdf"))
for pdf in pdf_files:
    extract_first_page_text(pdf)

